import json
import time
import urllib.error
import urllib.request
from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP

BASE = 'http://localhost:8080'

def request(method, path, token=None, data=None):
    global token_value
    while True:
        headers = {'Accept': 'application/json'}
        if token is not None:
            headers['Authorization'] = 'Bearer ' + token_value
        body = None
        if data is not None:
            body = json.dumps(data).encode()
            headers['Content-Type'] = 'application/json'
        req = urllib.request.Request(BASE + path, data=body, headers=headers, method=method)
        try:
            with urllib.request.urlopen(req, timeout=30) as resp:
                raw = resp.read()
                return json.loads(raw) if raw else None
        except urllib.error.HTTPError as exc:
            raw = exc.read().decode('utf-8', 'replace')
            if exc.code == 401 and token is not None:
                token_value = get_token()
                continue
            if exc.code == 429:
                wait = exc.headers.get('Retry-After')
                if wait is None:
                    try:
                        obj = json.loads(raw)
                        wait = obj.get('retry_after') or obj.get('wait_seconds')
                    except Exception:
                        pass
                if wait is None:
                    raise RuntimeError('Rate limited without a wait duration: ' + raw)
                print('Rate limited; waiting', wait, 'seconds', flush=True)
                time.sleep(float(wait))
                continue
            if exc.code >= 500:
                time.sleep(1)
                continue
            raise RuntimeError(f'{method} {path} failed with HTTP {exc.code}: {raw}')
        except (urllib.error.URLError, TimeoutError) as exc:
            print('Request error; retrying:', exc, flush=True)
            time.sleep(1)

def get_token():
    result = request('POST', '/token')
    if not result or not result.get('token'):
        raise RuntimeError('Token response missing token')
    return result['token']

token_value = get_token()
all_orders = []
seen_ids = set()
duplicates_skipped = 0
page = 1
while True:
    payload = request('GET', f'/orders?page={page}', token=True)
    if payload.get('page') "'!= page:
        raise RuntimeError(f'"'Unexpected page number in response: {payload.get(\"page\")} expected {page}')
    for order in payload.get('items', []):
        oid = order['id']
        if oid in seen_ids:
            duplicates_skipped += 1
        else:
            seen_ids.add(oid)
            all_orders.append(order)
    total_pages = payload.get('total_pages')
    if page >= total_pages:
        if payload.get('next') is not None:
            raise RuntimeError('Last page unexpectedly has a next link')
        break
    nxt = payload.get('next')
    if not nxt:
        raise RuntimeError(f'Missing next link on page {page}')
    page += 1

start = datetime(2025, 3, 1, tzinfo=timezone.utc)
end = datetime(2025, 6, 1, tzinfo=timezone.utc)
customers = {}
by_region = {'north': 0, 'south': 0, 'east': 0, 'west': 0}
order_count = 0
for order in all_orders:
    if order.get('status') "'!= '"'shipped':
        continue
    ts = order['placed_at']
    if ts.endswith('Z'):
        ts = ts[:-1] + '+00:00'
    placed_at = datetime.fromisoformat(ts).astimezone(timezone.utc)
    if not (start <= placed_at < end):
        continue
    cid = order['customer_id']
    if cid not in customers:
        customers[cid] = request('GET', f'/customers/{cid}', token=True)
    customer = customers[cid]
    discount = customer['discount_pct']
    discounted = (Decimal(order['amount_cents']) * Decimal(100 - discount) / Decimal(100)).quantize(Decimal('1'), rounding=ROUND_HALF_UP)
    by_region[customer['region']] += int(discounted)
    order_count += 1

result = {
    'total_cents': sum(by_region.values()),
    'order_count': order_count,
    'duplicates_skipped': duplicates_skipped,
    'by_region': by_region,
}
with open('/workspace/result.json', 'w') as f:
    json.dump(result, f, indent=2)
    f.write('\\n')
print(json.dumps(result, sort_keys=True))
print('Unique listings:', len(all_orders), 'pages:', page, 'customer records cached:', len(customers))
